import React, { useState } from 'react';
import api from '../api';

const DeterministicQR = ({ seed }) => {
    let hash = 0;
    for (let i = 0; i < seed.length; i++) {
        hash = ((hash << 5) - hash) + seed.charCodeAt(i);
        hash |= 0;
    }
    const size = 11;
    const rects = [];
    for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
            const isCorner = (r < 3 && c < 3) || (r < 3 && c >= size - 3) || (r >= size - 3 && c < 3);
            const filled = isCorner || (Math.abs((hash * (r + 3) * (c + 7) + r * 13 + c * 17)) % 3 === 0);
            if (filled) {
                rects.push(<rect key={`${r}-${c}`} x={c * 8 + 6} y={r * 8 + 6} width="7" height="7" rx="1.6" fill="#090d16" />);
            }
        }
    }
    return <svg viewBox="0 0 100 100" className="w-24 h-24 bg-white/95 p-2 rounded-2xl shadow-lg">{rects}</svg>;
};

const GateSimulator = ({ tickets, onRefreshTickets, onBuyMore, showToast }) => {
    const [gateName, setGateName] = useState('GATE-01 Main Entrance');
    const [manualToken, setManualToken] = useState('');
    const [scanState, setScanState] = useState('IDLE');
    const [statusTitle, setStatusTitle] = useState('Hold Near Reader');
    const [statusSub, setStatusSub] = useState('Tap "Scan at Gate" on any Wallet pass or enter a pass hash.');
    const [armOpen, setArmOpen] = useState(false);
    const [apiLog, setApiLog] = useState(JSON.stringify({
        endpoint: 'POST /api/v1/tickets/validate',
        node: 'RPI4-GATE-01',
        state: 'READY_NFC_OPTICAL'
    }, null, 2));

    const triggerScan = async (qrHash) => {
        try {
            const res = await api.post('/tickets/validate', { qrHash, gateName });
            setScanState('GRANTED');
            setStatusTitle('Verified — Gate Unlocked');
            setStatusSub(`${res.data.seatLabel} (${res.data.tier}) checked in at ${res.data.scannedAt}.`);
            setArmOpen(true);
            setTimeout(() => setArmOpen(false), 3000);

            setApiLog(JSON.stringify({
                request: { method: 'POST', path: '/api/v1/tickets/validate', qrHash, gate: gateName },
                response: { httpStatus: 200, ...res.data, gpioPin18: 'HIGH_3000MS' }
            }, null, 2));

            showToast(`Gate Unlocked for ${qrHash}`, 'success');
            onRefreshTickets();
        } catch (err) {
            const errData = err.response?.data || { code: 'ERROR', message: 'Validation failed' };
            setScanState('DENIED');
            setStatusTitle(`Pass Rejected — ${errData.code || 'DENIED'}`);
            setStatusSub(errData.message);

            setApiLog(JSON.stringify({
                request: { method: 'POST', path: '/api/v1/tickets/validate', qrHash, gate: gateName },
                response: { httpStatus: err.response?.status || 409, ...errData }
            }, null, 2));

            showToast(errData.message, 'error');
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 liquid-glass rounded-[28px] p-5 sm:p-6">
                <div>
                    <h2 className="text-xl font-bold tracking-tight text-white">Apple Wallet Passes &amp; Edge Reader</h2>
                    <p className="text-sm text-white/60">Tap an <span className="text-emerald-300 font-semibold">ACTIVE</span> pass to actuate the turnstile, or test anti-replay security on a <span className="text-rose-300 font-semibold">USED</span> pass.</p>
                </div>
                <button onClick={onBuyMore} className="px-5 py-2.5 rounded-full glass-pill-btn font-bold text-xs sm:text-sm self-start md:self-auto">
                    + Add Passes
                </button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
                {/* Left: Apple Wallet Boarding Passes */}
                <div className="lg:col-span-7 space-y-4">
                    <div className="flex items-center justify-between px-1">
                        <h3 className="text-xs font-semibold uppercase tracking-widest text-white/50">Wallet Passes ({tickets.length})</h3>
                        <span className="text-xs font-mono text-white/40">HMAC-SHA256 Signed</span>
                    </div>

                    {tickets.length === 0 ? (
                        <div className="liquid-glass rounded-[28px] p-10 text-center text-white/50 text-sm">
                            Your Wallet is empty. Explore events to add passes.
                        </div>
                    ) : (
                        tickets.map(tkt => {
                            const isActive = tkt.status === 'ACTIVE';
                            return (
                                <div key={tkt.id} className={`wallet-pass liquid-glass-card rounded-[28px] p-6 flex flex-col sm:flex-row items-center justify-between gap-5 ${!isActive ? 'opacity-75' : ''}`}>
                                    <div className="space-y-2.5 flex-1">
                                        <div className="flex flex-wrap items-center gap-2.5">
                                            {isActive ? (
                                                <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-emerald-400/20 text-emerald-200 border border-emerald-300/30">● Active Pass</span>
                                            ) : (
                                                <span className="px-3 py-1 rounded-full text-[11px] font-semibold bg-rose-400/20 text-rose-200 border border-rose-300/30">✕ Redeemed ({tkt.scannedAt})</span>
                                            )}
                                            <span className="font-mono text-xs text-white/50">{tkt.id}</span>
                                        </div>
                                        <h4 className="text-xl font-bold tracking-tight text-white">{tkt.eventTitle}</h4>
                                        <p className="text-xs text-white/65">{tkt.venue} • {tkt.date}</p>
                                        <div className="pt-1 flex flex-wrap items-center gap-2 text-xs font-mono">
                                            <span className="px-3 py-1 rounded-full bg-white/10 border border-white/15 text-white/90">{tkt.tier}</span>
                                            <span className="px-3 py-1 rounded-full bg-white/10 border border-white/15 text-amber-200">{tkt.seat}</span>
                                        </div>
                                        {!isActive && <p className="text-[11px] font-mono text-white/45 pt-1">Scanned at {tkt.scannedBy}</p>}
                                    </div>

                                    <div className="flex flex-col items-center gap-3 shrink-0 border-t sm:border-t-0 sm:border-l border-dashed border-white/20 pt-4 sm:pt-0 sm:pl-6 w-full sm:w-auto">
                                        <DeterministicQR seed={tkt.id} />
                                        <button onClick={() => triggerScan(tkt.id)} className={`w-full px-4 py-2 rounded-full font-bold text-xs transition ${isActive ? 'glass-pill-btn' : 'bg-rose-500/20 hover:bg-rose-500/30 text-rose-200 border border-rose-400/30'}`}>
                                            {isActive ? 'Scan at Gate' : 'Test Replay'}
                                        </button>
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>

                {/* Right: Spatial IoT Reader Pod */}
                <div className="lg:col-span-5 sticky top-24 liquid-glass rounded-[32px] overflow-hidden">
                    <div className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-white/[0.03]">
                        <div className="flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-sky-400 animate-pulse"></span>
                            <span className="font-mono text-xs font-semibold text-white/80">GATE READER</span>
                        </div>
                        <select value={gateName} onChange={(e) => setGateName(e.target.value)} className="liquid-well text-xs font-mono text-white rounded-full px-3 py-1.5 focus:outline-none">
                            <option value="GATE-01 Main Entrance" className="bg-slate-900">GATE-01 Main Entrance</option>
                            <option value="GATE-02 VIP North" className="bg-slate-900">GATE-02 VIP North</option>
                            <option value="GATE-03 East Wing" className="bg-slate-900">GATE-03 East Wing</option>
                        </select>
                    </div>

                    <div className="p-6 space-y-5">
                        {/* Optical Dynamic Island Reader Feedback */}
                        <div className={`rounded-[24px] p-6 text-center space-y-2.5 transition-all duration-300 border ${scanState === 'GRANTED' ? 'bg-emerald-500/20 border-emerald-300/50 led-green' : scanState === 'DENIED' ? 'bg-rose-500/20 border-rose-300/50 led-red' : 'liquid-well border-white/15'}`}>
                            <div className={`w-14 h-14 mx-auto rounded-full flex items-center justify-center font-bold text-2xl transition-all ${scanState === 'GRANTED' ? 'bg-emerald-400 text-slate-950 scale-110' : scanState === 'DENIED' ? 'bg-rose-500 text-white scale-110' : 'bg-white/10 border border-white/25 text-white'}`}>
                                {scanState === 'GRANTED' ? '✓' : scanState === 'DENIED' ? '✕' : '◎'}
                            </div>
                            <h4 className="font-bold text-base tracking-tight text-white">{statusTitle}</h4>
                            <p className="text-xs text-white/70 leading-relaxed">{statusSub}</p>
                        </div>

                        {/* Spring Turnstile Actuator */}
                        <div className="liquid-well rounded-2xl p-4">
                            <div className="flex items-center justify-between text-[11px] font-mono text-white/50 mb-3">
                                <span>GPIO RELAY PIN 18</span>
                                <span className={`font-semibold ${armOpen ? 'text-emerald-300' : 'text-white/70'}`}>{armOpen ? 'OPEN (3.0s)' : 'LOCKED'}</span>
                            </div>
                            <div className="relative h-14 bg-white/[0.04] rounded-xl border border-white/10 flex items-center px-4 overflow-hidden">
                                <div className="w-8 h-10 rounded-lg bg-white/20 border border-white/30 flex items-center justify-center text-[10px] font-mono font-bold text-white z-10">HUB</div>
                                <div className={`turnstile-arm h-3 w-48 rounded-r-full ml-1 shadow-lg ${armOpen ? 'turnstile-open bg-emerald-400' : 'bg-white/60'}`}></div>
                                <span className="ml-auto text-[10px] font-mono text-white/35">LANE</span>
                            </div>
                        </div>

                        <div className="flex gap-2">
                            <input type="text" value={manualToken} onChange={(e) => setManualToken(e.target.value)} placeholder="Enter pass token (TKT-AUR-8821)..." className="flex-1 px-4 py-2.5 rounded-full liquid-well text-xs font-mono text-white placeholder-white/35 focus:outline-none focus:border-white/40" />
                            <button onClick={() => manualToken.trim() && triggerScan(manualToken.trim().toUpperCase())} className="px-5 py-2.5 rounded-full glass-pill-btn font-bold text-xs">
                                Verify
                            </button>
                        </div>

                        <pre className="liquid-well rounded-2xl p-3.5 text-[11px] font-mono text-white/75 overflow-x-auto max-h-40 leading-relaxed">
              {apiLog}
            </pre>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default GateSimulator;
